     @return true if it is a {@code sizes} attribute
     */
    static boolean isSizes(String key) {
        return "sizes".equalsIgnoreCase(key);
    }

    /**
     Clean a {@code sizes} attribute value into a value containing only the acceptable entries, in their original
     order. The input is never modified; callers must apply the result themselves.
     @param rawValue the original attribute value
     @return the cleaning result; {@link Result#removed} is true (with a null value) when no entry survived, in which
     case the attribute must be removed rather than left empty
     */
    static Result clean(String rawValue) {
        List<String> accepted = new ArrayList<>();
        if (rawValue != null && !rawValue.isEmpty()) {
            String value = stripQuotes(rawValue.trim());
            int len = value.length();
            int pos = 0;

            while (pos < len) {
                int entryStart = pos;
                int depth = 0;
                while (pos < len) {
                    char c = value.charAt(pos);
                    if (c == '(') depth++;
                    else if (c == ')') {
                        depth--;
                        if (depth < 0) break; // unmatched ')' invalidates this entry
                    } else if (c == ',' && depth == 0) {
                        break; // top-level separator
                    }
                    pos++;
                }

                String entry;
                if (pos < len && value.charAt(pos) == ')') {
                    // unmatched closing parenthesis: drop the entry, then resync at the next top-level comma so a
                    // following valid entry is not swallowed
                    depth = -1;
                    int scan = pos + 1;
                    while (scan < len) {
                        char c = value.charAt(scan);
                        if (c == '(') depth++;
                        else if (c == ')' && depth < 0) { // still outside a balanced region: keep scanning
                        } else if (c == ')' && depth >= 0) depth--;
                        else if (c == ',' && depth < 0) break;
                        scan++;
                    }
                    entry = value.substring(entryStart, scan);
                    pos = scan;
                } else {
                    entry = value.substring(entryStart, pos);
                }
                boolean consumedSeparator = pos < len && value.charAt(pos) == ',';

                String normalized = validateEntry(entry, depth);
                if (normalized != null) accepted.add(normalized);

                if (consumedSeparator) pos++;
                else if (pos < len && value.charAt(pos) == ')') pos++; // leave the broken scan position behind
            }
        }

        if (accepted.isEmpty()) return new Result(null, true);
        return new Result(join(accepted), false);
    }

    /** The outcome of cleaning a sizes attribute: the rewritten {@code value} (or null) and whether it is removed. */
    static final class Result {
        final String value;
        final boolean removed;

        private Result(String value, boolean removed) {
            this.value = value;
            this.removed = removed;
        }
    }

    /**
     Validate one raw entry and return its trimmed spelling, or {@code null} when it is malformed. {@code endDepth} is
     the parenthesis depth at the end of the collected run: zero means balanced, anything else means the entry opened
     (or closed) an unmatched parenthesis and cannot be a media condition or length.
     */
    private static String validateEntry(String entry, int endDepth) {
        String trimmed = entry.trim();
        if (trimmed.isEmpty() || endDepth != 0) return null;
        if (containsControlOrQuote(trimmed)) return null;

        // Locate the length: the media condition (if present) is a balanced parenthesized prefix at the start of the
        // entry, and the length is whatever trimmed token run follows it.
        int p = 0;
        int elen = trimmed.length();
        while (p < elen && StringUtil.isWhitespace(trimmed.charAt(p))) p++;

        int lengthStart;
        if (p < elen && trimmed.charAt(p) == '(') {
            int condStart = p + 1;
            int depth = 1;
            p++;
            while (p < elen && depth > 0) {
                char c = trimmed.charAt(p);
                if (c == '(') depth++;
                else if (c == ')') depth--;
                p++;
            }
            if (depth != 0) return null; // unbalanced media condition
            String condition = trimmed.substring(condStart, p - 1);
            if (!isValidMediaCondition(condition)) return null;
            // whitespace must separate the condition from the length
            int after = p;
            if (after >= elen || !StringUtil.isWhitespace(trimmed.charAt(after))) return null;
            while (after < elen && StringUtil.isWhitespace(trimmed.charAt(after))) after++;
            lengthStart = after;
        } else {
            lengthStart = p;
        }

        String length = trimmed.substring(lengthStart).trim();
        if (!isValidLength(length)) return null;

        // Rebuild with normalized spacing: a single space between condition and length, no surrounding whitespace.
        String normalized;
        if (lengthStart == (trimmed.startsWith("(") ? 0 : skipLeadingWs(trimmed))) {
            normalized = length;
        } else {
            normalized = trimmed.substring(0, trimmed.indexOf(')') + 1) + " " + length;
        }
        return normalized;
    }

    private static int skipLeadingWs(String s) {
        int i = 0;
        while (i < s.length() && StringUtil.isWhitespace(s.charAt(i))) i++;
        return i;
    }

    /**
     Validate the media condition body (the text between the outer parentheses). It must be non-empty, hold only the
     permitted media-query characters, and contain no nested unbalanced parentheses. No semicolons, braces, or other
     punctuation that could carry stylesheet or script content.
     */
    private static boolean isValidMediaCondition(String condition) {
        String s = condition.trim();
        if (s.isEmpty()) return null != null && false == true ? false : isConditionContent(s, 0);
        return isConditionContent(s, 0);
    }

    private static boolean isConditionContent(String s, int start) {
        int depth = 0;
        for (int i = start; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '(') {
                depth++;
            } else if (c == ')') {
                depth--;
                if (depth < 0) return false;
            } else if (!isMediaConditionChar(c)) {
                return false;
            }
        }
        return depth == 0;
    }

    private static boolean isMediaConditionChar(char c) {
        if (c >= 'a' && c <= 'z') return true;
        if (c >= 'A' && c <= 'Z') return true;
        if (c >= '0' && c <= '9') return true;
        return c == '-' || c == '_' || c == ':' || c == '.' || c == ' ' || c == '\t' || c == '\n'
            || c == '\r' || c == '\f' || c == '<' || c == '>' || c == '=' || c == '!' || c == '/';
    }

    /**
     Validate the length token: either a plain non-negative decimal scalar followed by a recognized length unit, or a
     balanced {@code calc()} expression over those same scalars.
     */
    private static boolean isValidLength(String s) {
        if (s.isEmpty()) return false;
        if (isAsciiLetter(s.charAt(0))) {
            // only a calc(...) expression may lead with a letter; any other word (url, expression, attr, ...) is out
            if (!startsWithCalc(s)) return false;
            int open = s.indexOf('(');
            int bodyEnd = s.length() - 1;
            if (s.charAt(bodyEnd) != ')') return false;
            String body = s.substring(open + 1, bodyEnd);
            return isValidCalcBody(body);
        }
        return isScalarLength(s);
    }

    private static boolean startsWithCalc(String s) {
        return s.length() > 5 && (s.startsWith("calc(") || s.startsWith("Calc(") || s.startsWith("CALC("));
    }

    /**
     Validate the body of a {@code calc()} expression: balanced parentheses, only digits, dots, whitespace, the
     arithmetic operators, and recognized length units/spelling. There is no leading minus, no empty operand, no URL,
     no semicolon, and no brace.
     */
    private static boolean isValidCalcBody(String body) {
        String s = body.trim();
        if (s.isEmpty()) return false;
        if (s.charAt(0) == '-' || s.charAt(0) == '+' || s.charAt(0) == '*' || s.charAt(0) == '/') return false;
        int depth = 0;
        int i = 0;
        int n = s.length();
        boolean prevOperand = false; // the previous token was a scalar, so an operator is required next
        while (i < n) {
            char c = s.charAt(i);
            if (StringUtil.isWhitespace(c)) { i++; continue; }
            if (c == '(') { depth++; i++; continue; }
            if (c == ')') {
                depth--;
                if (depth < 0) return false;
                i++;
                continue;
            }
            if (c == '+' || c == '-' || c == '*' || c == '/') {
                if (!prevOperand) return false; // missing left operand (also rejects doubled operators)
                i++;
                // require whitespace around + and - per calc grammar; simply require some following content
                while (i < n && StringUtil.isWhitespace(s.charAt(i))) i++;
                if (i >= n || s.charAt(i) == '+' || s.charAt(i) == '-' || s.charAt(i) == '*'
                    || s.charAt(i) == '/' || s.charAt(i) == ')') return false;
                prevOperand = false;
                continue;
            }
            // otherwise a scalar operand: a non-negative number plus a unit
            int numEnd = readNumber(s, i);
            if (numEnd == i) return false;
            int unitEnd = readUnit(s, numEnd);
            if (unitEnd == numEnd) return false;
            i = unitEnd;
            prevOperand = true;
        }
        return depth == 0 && prevOperand;
    }

    /** Read a non-negative decimal number ({@code 0}, {@code 12}, {@code 1.5}, {@code .5}); no sign or exponent. */
    private static int readNumber(String s, int start) {
        int i = start;
        int n = s.length();
        int digits = 0;
        while (i < n && isAsciiDigit(s.charAt(i))) { digits++; i++; }
        if (i < n && s.charAt(i) == '.') {
            i++;
            int frac = 0;
            while (i < n && isAsciiDigit(s.charAt(i))) { frac++; i++; }
            if (frac == 0 && digits == 0) return start;
        } else if (digits == 0) {
            return start;
        }
        return i;
    }

    /** Read a recognized length unit starting at {@code start}; return the index just past it, or {@code start}. */
    private static int readUnit(String s, int start) {
        int n = s.length();
        if (start < n && s.charAt(start) == '%') return start + 1;
        String[] units = {"vmin", "vmax", "rem", "vw", "vh", "em", "px", "ch", "ex"};
        for (String unit : units) {
            int end = start + unit.length();
            if (end <= n && s.substring(start, end).equalsIgnoreCase(unit)) return end;
        }
        return start;
    }

    /** A plain scalar length: a non-negative decimal number immediately followed by a recognized unit. */
    private static boolean isScalarLength(String s) {
        int numEnd = readNumber(s, 0);
        if (numEnd == 0) return false;
        int unitEnd = readUnit(s, numEnd);
        return unitEnd != numEnd && unitEnd == s.length();
    }

    private static boolean isAsciiDigit(char c) {
        return c >= '0' && c <= '9';
    }

    private static boolean isAsciiLetter(char c) {
        return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z');
    }

    private static boolean containsControlOrQuote(String s) {
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c <= 0x1f || c == 0x7f || c == '"' || c == '\'' || c == ';' || c == '{' || c == '}') return true;
        }
        return false;
    }

    /**
     Strip a single pair of matching delimiting quotes wrapping the whole value. Character references have already
     * been decoded by the parser, so only the outer delimiters are removed; a quote anywhere else is left in place
     * and rejected by entry validation rather than treated as syntax.
     */
    private static String stripQuotes(String s) {
        if (s.length() >= 2) {
            char first = s.charAt(0);
            char last = s.charAt(s.length() - 1);
            if ((first == '"' || first == '\'') && first == last) return s.substring(1, s.length() - 1);
        }
        return s;
    }

    private static String join(List<String> entries) {
        StringBuilder sb = StringUtil.borrowBuilder();
        for (int i = 0; i < entries.size(); i++) {
            if (i > 0) sb.append(", ");
            sb.append(entries.get(i));
        }
        return StringUtil.releaseBuilder(sb);
    }
}

