40	     rather than treated as an ordinary opaque attribute.
41	     @param key the attribute key to test
42	     @return true if it is a {@code sizes} attribute
43	     */
44	    static boolean isSizes(String key) {
45	        return "sizes".equalsIgnoreCase(key);
46	    }
47	
48	    /**
49	     Clean a {@code sizes} attribute value into a value containing only the acceptable entries, in their original
50	     order. The input is never modified; callers must apply the result themselves.
51	     @param rawValue the original attribute value
52	     @return the cleaning result; {@link Result#removed} is true (with a null value) when no entry survived, in which
53	     case the attribute must be removed rather than left empty
54	     */
55	    static Result clean(String rawValue) {
56	        List<String> accepted = new ArrayList<>();
57	        int dropped = 0;
58	        if (rawValue != null && !rawValue.isEmpty()) {
59	            String value = stripQuotes(rawValue.trim()); // a quote pair wrapping the whole attribute value
60	            int len = value.length();
61	            int pos = 0;
62	
63	            while (pos < len) {
64	                // Splitting loop: collect one entry. Commas separate entries only at depth zero; a comma inside a
65	                // balanced parenthesized region is entry content. An unmatched ')' ends the entry at that point (the
66	                // entry is rejected); an unmatched '(' would otherwise run to the end, so the first comma inside it
67	                // is remembered and used as a resync point when the group never closes, so a following valid entry
68	                // is not swallowed.
69	                int entryStart = pos;
70	                int depth = 0;
71	                int deepComma = -1;
72	                boolean strayClose = false;
73	                while (pos < len) {
74	                    char c = value.charAt(pos);
75	                    if (c == '(') {
76	                        depth++;
77	                    } else if (c == ')') {
78	                        depth--;
79	                        if (depth < 0) strayClose = true;
80	                    } else if (c == ',') {
81	                        if (depth <= 0) break; // top-level separator
82	                        if (deepComma < 0) deepComma = pos; // tentative separator inside an unclosed group
83	                    }
84	                    pos++;
85	                }
86	
87	                String entry;
88	                if (pos >= len && depth > 0 && deepComma >= 0) {
89	                    // the group never closed: reject the run up to its first inner comma, and restart after it
90	                    entry = value.substring(entryStart, deepComma);
91	                    pos = deepComma;
92	                } else {
93	                    entry = value.substring(entryStart, pos);
94	                }
95	                boolean balanced = depth == 0 && !strayClose;
96	
97	                String normalized = validateEntry(entry, balanced);
98	                if (normalized != null) accepted.add(normalized);
99	                else if (!entry.trim().isEmpty() || !balanced) dropped++;
100	
101	                if (pos < len && value.charAt(pos) == ',') pos++; // consume the separator
102	            }
103	        }
104	
105	        if (accepted.isEmpty()) return new Result(null, dropped, true);
106	        return new Result(join(accepted), dropped, false);
107	    }
108	
109	    /** The outcome of cleaning a sizes attribute: the rewritten {@code value} (or null) and statistics. */
110	    static final class Result {
111	        final String value;
112	        final int droppedEntries;
113	        final boolean removed;
114	
115	        private Result(String value, int droppedEntries, boolean removed) {
116	            this.value = value;
117	            this.droppedEntries = droppedEntries;
118	            this.removed = removed;
119	        }
120	    }
121	
122	    /**
123	     Validate one raw entry and return its trimmed spelling, or {@code null} when it is malformed. {@code balanced}
124	     reports whether the collected run ended at parenthesis depth zero; an unbalanced run can never be a valid media
125	     condition or length.
126	     <p>
127	     A media condition may span several parenthesized groups joined by keywords ({@code (min-width: 30em) and
128	     (orientation: landscape)}), so the length is located at the end of the entry: either a whitespace-free scalar
129	     suffix, or a balanced {@code calc(...)} group. Anything before it is the optional media condition.
130	     </p>
131	     */
132	    private static String validateEntry(String entry, boolean balanced) {
133	        String trimmed = stripQuotes(entry.trim()); // a quote pair delimiting this single entry
134	        if (trimmed.isEmpty() || !balanced) return null;
135	        if (containsUnsafeChar(trimmed)) return null;
136	
137	        int lengthStart = findLengthStart(trimmed);
138	        if (lengthStart < 0) return null;
139	
140	        String length = trimmed.substring(lengthStart).trim();
141	        if (!isValidLength(length)) return null;
142	
143	        if (lengthStart > 0) {
144	            String condition = trimmed.substring(0, lengthStart);
145	            // the condition and the length must be separated by whitespace
146	            if (!StringUtil.isWhitespace(condition.charAt(condition.length() - 1))) return null;
147	            if (!isValidMediaCondition(condition.trim())) return null;
148	        }
149	        return trimmed;
150	    }
151	
152	    /**
153	     Return the index at which the trailing length begins, or {@code -1} when the entry does not end in a recognizable
154	     length. A {@code calc(...)} length ends in a balanced {@code )} whose matching {@code (} is preceded by the word
155	     * {@code calc} at a token boundary; any other ending must be a single whitespace-free scalar token.
156	     */
157	    private static int findLengthStart(String s) {
158	        int n = s.length();
159	        if (s.charAt(n - 1) == ')') {
160	            int depth = 0;
161	            int i = n - 1;
162	            do {
163	                char c = s.charAt(i);
164	                if (c == ')') depth++;
165	                else if (c == '(') depth--;
166	                i--;
167	            } while (i >= 0 && depth > 0);
168	            int open = i + 1; // index of the matching '('
169	            int wordStart = open;
170	            while (wordStart > 0 && isAsciiLetter(s.charAt(wordStart - 1))) wordStart--;
171	            if (open - wordStart == 4 && s.regionMatches(true, wordStart, "calc", 0, 4)
172	                && (wordStart == 0 || StringUtil.isWhitespace(s.charAt(wordStart - 1)))) {
173	                return wordStart;
174	            }
175	        }
176	        int ws = s.length() - 1;
177	        while (ws >= 0 && !StringUtil.isWhitespace(s.charAt(ws))) ws--;
178	        return ws + 1;
179	    }
180	
181	    /**
182	     Validate the media condition text. It must be non-empty, hold only the permitted media-query characters, and
183	     have balanced nested parentheses. No semicolons, braces, quotes, or other punctuation that could carry
184	     stylesheet or script content; a script scheme smuggled in with whitespace inside its name is also rejected.
185	     */
186	    private static boolean isValidMediaCondition(String condition) {
187	        String s = condition.trim();
188	        if (s.isEmpty() || s.charAt(0) != '(' || s.charAt(s.length() - 1) != ')') return false;
189	        int depth = 0;
190	        for (int i = 0; i < s.length(); i++) {
191	            char c = s.charAt(i);
192	            if (c == '(') {
193	                depth++;
194	            } else if (c == ')') {
195	                depth--;
196	                if (depth < 0) return false;
197	            } else if (!isMediaConditionChar(c)) {
198	                return false;
199	            }
200	        }
201	        if (depth != 0) return false;
202	        // whitespace inside a smuggled scheme name (e.g. "java\tscript:") is flattened before the substring test
203	        String flattened = StringUtil.normaliseWhitespace(s.toLowerCase()).replace(" ", "");
204	        return !flattened.contains("javascript:") && !flattened.contains("vbscript:")
205	            && !flattened.contains("livescript:");
206	    }
207	
208	    private static boolean isMediaConditionChar(char c) {
209	        if (c >= 'a' && c <= 'z') return true;
210	        if (c >= 'A' && c <= 'Z') return true;
211	        if (c >= '0' && c <= '9') return true;
212	        return c == '-' || c == ':' || c == '.' || c == '<' || c == '>' || c == '=' || c == '!' || c == '/'
213	            || StringUtil.isWhitespace(c);
214	    }
215	
216	    /**
217	     Validate the length token: either a plain non-negative decimal scalar followed by a recognized length unit, or a
218	     balanced {@code calc()} expression over those same scalars and units.
219	     */
220	    private static boolean isValidLength(String s) {
221	        if (s.isEmpty()) return false;
222	        if (isAsciiLetter(s.charAt(0))) {
223	            // only a calc(...) expression may lead with a letter; any other word (url, expression, attr, ...) is out
224	            if (!startsWithCalc(s)) return false;
225	            if (s.charAt(s.length() - 1) != ')') return false;
226	            return isValidCalcBody(s.substring(5, s.length() - 1));
227	        }
228	        return isScalarLength(s);
229	    }
230	
231	    private static boolean startsWithCalc(String s) {
232	        return s.length() > 5 && s.regionMatches(true, 0, "calc(", 0, 5);
233	    }
234	
235	    /**
236	     Validate the body of a {@code calc()} expression: balanced parentheses, and only non-negative scalars with
237	     recognized units (or bare numbers) joined by the {@code + - * /} operators. There is no leading minus, no empty
238	     operand, no URL, no semicolon, and no brace.
239	     */
240	    private static boolean isValidCalcBody(String body) {
241	        String s = body.trim();
242	        if (s.isEmpty()) return false;
243	        char first = s.charAt(0);
244	        if (first == '-' || first == '+' || first == '*' || first == '/') return false;
245	
246	        int depth = 0;
247	        int i = 0;
248	        int n = s.length();
249	        boolean prevOperand = false; // the previous token was a scalar or ')', so an operator may come next
250	        while (i < n) {
251	            char c = s.charAt(i);
252	            if (StringUtil.isWhitespace(c)) { i++; continue; }
253	            if (c == '(') {
254	                if (prevOperand) return false; // an operand must be followed by an operator, not a group
255	                depth++;
256	                i++;
257	                continue;
258	            }
259	            if (c == ')') {
260	                depth--;
261	                if (depth < 0 || !prevOperand) return false; // empty group or unbalanced close
262	                i++;
263	                continue;
264	            }
265	            if (c == '+' || c == '-' || c == '*' || c == '/') {
266	                if (!prevOperand) return false; // missing left operand (also rejects doubled operators)
267	                prevOperand = false;
268	                i++;
269	                continue;
270	            }
271	            if (isAsciiLetter(c)) {
272	                // a letter may only appear as the unit of the scalar just read; a bare word (url, nested calc, ...)
273	                // is never an operand
274	                return false;
275	            }
276	            // otherwise a scalar operand: a non-negative number with an optional recognized unit
277	            int numEnd = readNumber(s, i);
278	            if (numEnd == i) return false;
279	            int afterUnit = readUnit(s, numEnd);
280	            if (afterUnit != numEnd) {
281	                i = afterUnit; // a unit followed the number
282	            } else {
283	                i = numEnd; // bare number (legal inside calc), but never a bare word or unknown unit
284	                if (i < n && isAsciiLetter(s.charAt(i))) return false;
285	            }
286	            // the operand must end at whitespace, an operator, a parenthesis, or the end of the body
287	            if (i < n) {
288	                char next = s.charAt(i);
289	                if (!StringUtil.isWhitespace(next) && next != '+' && next != '-' && next != '*'
290	                    && next != '/' && next != ')') return false;
291	            }
292	            prevOperand = true;
293	        }
294	        return depth == 0 && prevOperand;
295	    }
296	
297	    /** Read a non-negative decimal number ({@code 0}, {@code 12}, {@code 1.5}, {@code .5}); no sign or exponent. */
298	    private static int readNumber(String s, int start) {
299	        int i = start;
300	        int n = s.length();
301	        int digits = 0;
302	        while (i < n && isAsciiDigit(s.charAt(i))) { digits++; i++; }
303	        if (i < n && s.charAt(i) == '.') {
304	            i++;
305	            int frac = 0;
306	            while (i < n && isAsciiDigit(s.charAt(i))) { frac++; i++; }
307	            if (frac == 0 && digits == 0) return start; // a lone dot is not a number
308	        } else if (digits == 0) {
309	            return start;
310	        }
311	        return i;
312	    }
313	
314	    /** Read a recognized length unit starting at {@code start}; return the index just past it, or {@code start}. */
315	    private static int readUnit(String s, int start) {
316	        int n = s.length();
317	        if (start < n && s.charAt(start) == '%') return start + 1;
318	        String[] units = {"vmin", "vmax", "rem", "vw", "vh", "em", "px", "ch", "ex"};
319	        for (String unit : units) {
320	            int end = start + unit.length();
321	            if (end <= n && s.regionMatches(true, start, unit, 0, unit.length())) return end;
322	        }
323	        return start;
324	    }
325	
326	    /** A plain scalar length: a non-negative decimal number immediately followed by a recognized unit. */
327	    private static boolean isScalarLength(String s) {
328	        int numEnd = readNumber(s, 0);
329	        if (numEnd == 0) return false;
330	        int unitEnd = readUnit(s, numEnd);
331	        return unitEnd != numEnd && unitEnd == s.length();
332	    }
333	
334	    private static boolean isAsciiDigit(char c) {
335	        return c >= '0' && c <= '9';
336	    }
337	
338	    private static boolean isAsciiLetter(char c) {
339	        return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z');
340	    }
341	
342	    /**
343	     Reject characters that can never appear in a valid entry: control characters (other than HTML whitespace),
344	     quotes, semicolons, and braces. These are the characters that could smuggle stylesheet or script content through
345	     a length or media condition.
346	     */
347	    private static boolean containsUnsafeChar(String s) {
348	        for (int i = 0; i < s.length(); i++) {
349	            char c = s.charAt(i);
350	            if (c == '"' || c == '\'' || c == ';' || c == '{' || c == '}') return true;
351	            if (c <= 0x1f && !StringUtil.isWhitespace(c)) return true;
352	            if (c == 0x7f) return true;
353	        }
354	        return false;
355	    }
356	
357	    /**
358	     Strip a single pair of matching delimiting quotes wrapping the whole value. The delimiters are parse-time syntax
359	     only; a quote anywhere else is left in place and rejected by entry validation rather than treated as syntax.
360	     */
361	    private static String stripQuotes(String s) {
362	        if (s.length() >= 2) {
363	            char first = s.charAt(0);
364	            char last = s.charAt(s.length() - 1);
365	            if ((first == '"' || first == '\'') && first == last) return s.substring(1, s.length() - 1);
366	        }
367	        return s;
368	    }
369	
370	    private static String join(List<String> entries) {
371	        StringBuilder sb = StringUtil.borrowBuilder();
372	        for (int i = 0; i < entries.size(); i++) {
373	            if (i > 0) sb.append(", ");
374	            sb.append(entries.get(i));
375	        }
376	        return StringUtil.releaseBuilder(sb);
377	    }
378	}
