/**
 Strip a single pair of matching delimiting quotes wrapping the whole value. The delimiters are parse-time syntax
 only; a quote anywhere else is left in place and rejected by entry validation rather than treated as syntax.
 */
private static String stripQuotes(String s) {
    if (s.length() >= 2) {
        char first = s.charAt(0);
        char last = s.charAt(s.length() - 1);
        if ((first == '"' || first == '\'') && first == last) return s.substring(1, s.length() - 1);
    }
    return s;
}

