        }
        // idempotence: clean again and reparse-clean must be stable
        String once = out;
        String twice = new org.jsoup.safety.Cleaner(sl).clean(Jsoup.parseBodyFragment(once)).body().html();
        if (!once.equals(twice)) throw new AssertionError("not idempotent: [" + v.replace("\n","\\n") + "] -> " + once + " -> " + twice);
    }
}
