import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.safety.Cleaner;
import org.jsoup.safety.Safelist;
import java.util.Random;

public class Fuzz {
    public static void main(String[] args) {
        Safelist sl = Safelist.relaxed()
            .addTags("picture", "source")
            .addAttributes("img", "srcset", "sizes")
            .addAttributes("source", "srcset", "sizes", "media", "type");
        char[] alphabet = {
            '0','1','9','a','z','m','w','p','x','e','r','v','c','h','(',')',',',' ','\t',
            ':',';','-','+','*','/','.','%','<','>','=','!','"','\'','{','}','[',']','#','@','&',
            'u','l','s','i','n','g','\\','`','|','?','~','^','\u0000','\t','\u007f'
        };
        String[] payloads = {
            "javascript:alert(1)", "java\tscript:x", "url(javascript:x)", "calc(100vw - url(x))",
            "expression(alert(1))", "100vw; background:url(x)", "(x:data:text/html,x) 1px",
            "{{7*'7'}}", "calc(100vw + -1px)", "calc(100vw - -1px)",
            "() 1px", "(a) (b) 1px", "100vw 100vh", "calc(calc(1px + 2px) + 3px)",
            "calc(1px + calc(2px * 3) - 4em)", ".5em", "0.0%", "1PX", "1Px"
        };
        Random rnd = new Random(42);
        int n = 200000;
        for (int i = 0; i < n; i++) {
            StringBuilder sb = new StringBuilder();
            int len = 1 + rnd.nextInt(30);
            for (int j = 0; j < len; j++) sb.append(alphabet[rnd.nextInt(alphabet.length)]);
            check(sb.toString(), sl);
        }
        for (String p : payloads) check(p, sl);
        System.out.println("ALL OK");
    }

    static void check(String v, Safelist sl) {
        String html = "<img sizes='" + v.replace("'", "&apos;") + "'>";
        Cleaner cleaner = new Cleaner(sl);
        Document d;
        try {
            d = cleaner.clean(Jsoup.parseBodyFragment(html));
        } catch (RuntimeException e) {
            throw new AssertionError("threw on [" + esc(v) + "]: " + e, e);
        }
        String out = d.body().html();
        String lc = out.toLowerCase();
        if (lc.contains("javascript") || lc.contains("vbscript") || lc.contains("url(")
            || lc.contains("{{") || lc.contains(";") || lc.contains("{") || lc.contains("}")) {
            throw new AssertionError("bad output for [" + esc(v) + "] -> " + out);
        }
